export const SMART_LOCK_API='https://spacego-lock-api.slepovnew2.chatgpt.site';
const validId=/^d_[a-f0-9]{32}$/;
export function smartLockUrl(id){if(!validId.test(id||''))throw new Error('Неверный идентификатор устройства.');return SMART_LOCK_API+'/access/'+id;}
export function publicDeviceLink(id,base=location.href){if(!validId.test(id||''))throw new Error('Для пространства не подключено QR-устройство.');const url=new URL(base);url.search='';url.hash='device/'+id;return url.href;}
export function renderSmartLock(main,id){
 const device=id&&validId.test(id);main.innerHTML='<section class="locks-page"><a class="text-button" href="#search">← К пространствам</a><h1>'+(id?'Доступ к устройству':'SPACEGO Smart Lock')+'</h1><p class="locks-lead">'+(id?'QR на экране определяет устройство. Вход разрешается только после проверки вашей брони.':'ESP32‑2432S028R с TFT-экраном 2.8″. На устройстве только QR: сенсор и PIN-коды не используются.')+'</p>'+(id&&!device?'<p class="test-note">Ссылка устройства некорректна. Отсканируйте QR на экране ещё раз.</p>':device?'<section><h2>Проверка доступа</h2><p>Войдите в аккаунт, на который владелец подтвердил бронирование. Нажатие кнопки ниже открывает страницу проверки; реле сработает только после отдельного запроса «Открыть ворота» и разрешения сервера.</p><a class="button primary" href="'+smartLockUrl(id)+'">Перейти к моему доступу</a><p class="mini-note">Идентификатор: '+id+'</p></section>':'<section><h2>Арендаторам</h2><p>Отсканируйте QR с экрана ворот, войдите в аккаунт и запросите открытие по активной оплаченной брони.</p></section>')+'<section><h2>Владельцам</h2><p>Подключите ESP32, создайте устройство и подтвердите бронирования в кабинете. Оплата отмечается владельцем после фактического получения средств.</p><a class="button" href="'+SMART_LOCK_API+'/owner">Устройства и бронирования</a></section><section class="locks-note"><h2>Как выдаётся доступ</h2><ol><li>Владелец подключает устройство и выдаёт QR-ссылку.</li><li>Арендатор запрашивает серверную бронь и оплачивает её владельцу.</li><li>Владелец подтверждает срок аренды и получение оплаты.</li><li>Сервер разрешает конкретному ESP32 один импульс реле.</li></ol><p class="mini-note">Демобронирования каталога хранятся в браузере и не разрешают открытие физического устройства.</p></section></section>';
}
